/* ============================================
   GlobalStone — Global Commercial Real Estate
   Design System: Corporate, Professional, Elegant
   Primary: #0A1628 (Deep Navy)
   Secondary: #012A2D (Dark Teal)
   Accent: #C9A227 (Refined Gold)
   Neutral: #E6E6E6 (Light Gray)
   ============================================ */

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');

/* CSS Variables */
:root {
  --color-primary: #0A1628;
  --color-primary-light: #1a2a42;
  --color-secondary: #012A2D;
  --color-accent: #C9A227;
  --color-accent-hover: #b08d1f;
  --color-white: #FFFFFF;
  --color-gray-50: #F8FAFC;
  --color-gray-100: #F1F5F9;
  --color-gray-200: #E2E8F0;
  --color-gray-300: #CBD5E1;
  --color-gray-400: #94A3B8;
  --color-gray-500: #64748B;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1E293B;
  --color-gray-900: #0F172A;
  --color-neutral: #E6E6E6;
  --color-border: rgba(255,255,255,0.12);
  --color-border-light: #E2E8F0;

  --font-heading: 'Playfair Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;
  --spacing-4xl: 6rem;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  --container-max: 1280px;
  --nav-height: 72px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background-color: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-primary);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.125rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  margin-bottom: var(--spacing-md);
}

/* Utility Classes */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--spacing-xl);
  padding-right: var(--spacing-xl);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-sm) var(--spacing-md);
  z-index: 10000;
  transition: top var(--transition-fast);
}
.skip-link:focus {
  top: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  padding: 0.75rem 1.5rem;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.025em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  min-height: 44px;
}

.btn-primary {
  background-color: var(--color-accent);
  color: var(--color-primary);
  border: 2px solid var(--color-accent);
}
.btn-primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-white);
  border: 2px solid var(--color-white);
}
.btn-secondary:hover {
  background-color: var(--color-white);
  color: var(--color-primary);
}

.btn-outline-dark {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline-dark:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* ============================================
   HEADER & NAVIGATION
   ============================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background-color: var(--color-primary);
  z-index: 1000;
  transition: background-color var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background-color: rgba(10, 22, 40, 0.98);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--color-accent);
}

/* Desktop Navigation */
.nav-desktop {
  display: none;
}

@media (min-width: 1024px) {
  .nav-desktop {
    display: flex;
    align-items: center;
    gap: var(--spacing-xl);
  }
}

.nav-link {
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  letter-spacing: 0.01em;
  padding: var(--spacing-sm) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-white);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.mega-menu-trigger {
  position: relative;
}

.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-10px);
  width: 720px;
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  padding: var(--spacing-xl);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
}

.mega-menu-trigger:hover .mega-menu,
.mega-menu-trigger:focus-within .mega-menu,
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.mega-menu::before {
  content: '';
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-bottom: 8px solid var(--color-white);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
}

.mega-menu-title {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-gray-400);
  margin-bottom: var(--spacing-md);
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.mega-menu-item {
  display: block;
  padding: var(--spacing-sm) 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-800);
  transition: color var(--transition-fast), transform var(--transition-fast);
}

.mega-menu-item:hover {
  color: var(--color-accent-hover);
  transform: translateX(4px);
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: var(--spacing-sm);
  z-index: 1001;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-white);
  transition: all var(--transition-base);
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}
.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

@media (min-width: 1024px) {
  .menu-toggle {
    display: none;
  }
}

/* Mobile Navigation */
.nav-mobile {
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-primary);
  padding: var(--spacing-xl);
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  z-index: 999;
}

.nav-mobile.open {
  transform: translateX(0);
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.mobile-nav-link {
  display: block;
  padding: var(--spacing-md) 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-white);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--color-white);
  border-bottom: 1px solid rgba(255,255,255,0.1);
  cursor: pointer;
}

.mobile-accordion-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
}

.mobile-accordion-header[aria-expanded="true"] .mobile-accordion-icon {
  transform: rotate(180deg);
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.mobile-accordion-content.open {
  max-height: 500px;
}

.mobile-accordion-inner {
  padding: var(--spacing-md) 0 var(--spacing-md) var(--spacing-lg);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.mobile-accordion-inner a {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.75);
  padding: var(--spacing-xs) 0;
}

.mobile-accordion-inner a:hover {
  color: var(--color-accent);
}

/* ============================================
   HERO SECTION
   ============================================ */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding-top: var(--nav-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  z-index: 0;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.92) 0%, rgba(10,22,40,0.75) 50%, rgba(1,42,45,0.65) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: var(--spacing-3xl) var(--spacing-xl);
}

.hero-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-accent);
  margin-bottom: var(--spacing-lg);
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.75rem);
  font-weight: 700;
  color: var(--color-white);
  line-height: 1.1;
  margin-bottom: var(--spacing-lg);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: rgba(255,255,255,0.85);
  line-height: 1.7;
  margin-bottom: var(--spacing-2xl);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
  justify-content: center;
}

/* Hero variant for interior pages */
.hero-sm {
  min-height: 50vh;
}

.hero-sm .hero-title {
  font-size: clamp(1.75rem, 4vw, 3rem);
}

/* ============================================
   SECTIONS
   ============================================ */
.section {
  padding: var(--spacing-4xl) 0;
}

.section-alt {
  background-color: var(--color-gray-50);
}

.section-dark {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3 {
  color: var(--color-white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto var(--spacing-3xl);
}

.section-header h2 {
  margin-bottom: var(--spacing-md);
}

.section-header p {
  color: var(--color-gray-500);
  font-size: 1.0625rem;
}

.section-dark .section-header p {
  color: rgba(255,255,255,0.7);
}

/* ============================================
   FEATURED INSIGHTS
   ============================================ */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-xl);
}

.insight-card {
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-image {
  width: 100%;
  height: 200px;
  background-size: cover;
  background-position: center;
}

.insight-card-body {
  padding: var(--spacing-lg);
}

.insight-card-tag {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-accent-hover);
  margin-bottom: var(--spacing-sm);
}

.insight-card-title {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-primary);
  line-height: 1.4;
  margin-bottom: var(--spacing-sm);
}

.insight-card-meta {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

/* ============================================
   ANNOUNCEMENT BANNER
   ============================================ */
.announcement-banner {
  background-color: var(--color-secondary);
  padding: var(--spacing-md) 0;
}

.announcement-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-md);
  text-align: center;
}

.announcement-text {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-white);
}

.announcement-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: color var(--transition-fast);
}

.announcement-link:hover {
  color: var(--color-white);
}

/* ============================================
   ABOUT STATEMENT
   ============================================ */
.about-statement {
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}

.about-statement p {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 400;
  line-height: 1.5;
  color: var(--color-primary);
  margin-bottom: var(--spacing-xl);
}

/* ============================================
   WHAT WE DO (TABBED)
   ============================================ */
.tabs-wrapper {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--spacing-3xl);
  align-items: start;
}

@media (max-width: 768px) {
  .tabs-wrapper {
    grid-template-columns: 1fr;
    gap: var(--spacing-xl);
  }
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
  border-left: 2px solid var(--color-gray-200);
}

.tab-btn {
  position: relative;
  padding: var(--spacing-md) var(--spacing-lg);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-500);
  text-align: left;
  transition: color var(--transition-fast), background-color var(--transition-fast);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

.tab-btn::before {
  content: '';
  position: absolute;
  left: -2px;
  top: 0;
  bottom: 0;
  width: 2px;
  background-color: transparent;
  transition: background-color var(--transition-fast);
}

.tab-btn:hover {
  color: var(--color-gray-700);
  background-color: var(--color-gray-50);
}

.tab-btn.active {
  color: var(--color-primary);
  background-color: var(--color-gray-50);
  font-weight: 600;
}

.tab-btn.active::before {
  background-color: var(--color-accent);
}

.tabs-panels {
  position: relative;
  min-height: 300px;
}

.tab-panel {
  opacity: 0;
  visibility: hidden;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  transform: translateX(20px);
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
}

.tab-panel.active {
  opacity: 1;
  visibility: visible;
  position: relative;
  transform: translateX(0);
}

.tab-panel h3 {
  margin-bottom: var(--spacing-md);
}

.tab-panel p {
  color: var(--color-gray-600);
  line-height: 1.7;
  margin-bottom: var(--spacing-xl);
}

/* ============================================
   NEWSLETTER
   ============================================ */
.newsletter-box {
  background-color: var(--color-primary-light);
  border-radius: var(--radius-lg);
  padding: var(--spacing-3xl);
  text-align: center;
}

.newsletter-box h3 {
  color: var(--color-white);
  margin-bottom: var(--spacing-sm);
}

.newsletter-box p {
  color: rgba(255,255,255,0.75);
  margin-bottom: var(--spacing-xl);
}

/* ============================================
   COMMITMENT PILLARS
   ============================================ */
.pillars-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-xl);
}

.pillar-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: var(--spacing-2xl) var(--spacing-xl);
  transition: box-shadow var(--transition-base), border-color var(--transition-base);
}

.pillar-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-gray-300);
}

.pillar-card h4 {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
}

.pillar-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
  margin-bottom: var(--spacing-lg);
}

.pillar-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent-hover);
  transition: color var(--transition-fast);
}

.pillar-link:hover {
  color: var(--color-primary);
}

/* ============================================
   SERVICE CATEGORIES
   ============================================ */
.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: var(--spacing-xl);
}

.service-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: var(--spacing-2xl);
  transition: box-shadow var(--transition-base), border-color var(--transition-base), transform var(--transition-base);
}

.service-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: var(--color-gray-300);
  transform: translateY(-4px);
}

.service-card h3 {
  font-family: var(--font-heading);
  font-size: 1.375rem;
  margin-bottom: var(--spacing-md);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
  margin-bottom: var(--spacing-lg);
}

.service-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent-hover);
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-sm);
  transition: color var(--transition-fast), gap var(--transition-fast);
}

.service-link:hover {
  color: var(--color-primary);
  gap: var(--spacing-md);
}

.service-link svg {
  width: 16px;
  height: 16px;
}

/* ============================================
   CAPABILITIES GRID
   ============================================ */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-xl);
}

.capability-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: var(--spacing-2xl);
  transition: box-shadow var(--transition-base), border-color var(--transition-base);
}

.capability-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: var(--spacing-sm);
}

.capability-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

/* ============================================
   INTRO STATEMENT
   ============================================ */
.intro-statement {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.intro-statement p {
  font-size: 1.125rem;
  color: var(--color-gray-600);
  line-height: 1.8;
}

/* ============================================
   FEATURED TOPICS
   ============================================ */
.topics-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.topic-item {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  padding: var(--spacing-md) var(--spacing-lg);
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-sm);
  font-weight: 500;
  color: var(--color-gray-700);
  transition: border-color var(--transition-fast), color var(--transition-fast);
}

.topic-item:hover {
  border-color: var(--color-accent);
  color: var(--color-primary);
}

.topic-item::before {
  content: '';
  width: 6px;
  height: 6px;
  background-color: var(--color-accent);
  border-radius: 50%;
  flex-shrink: 0;
}

/* ============================================
   PARTNERSHIP HIGHLIGHT
   ============================================ */
.partnership-block {
  background-color: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: var(--spacing-3xl);
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}

.partnership-block p {
  font-size: 1.0625rem;
  color: var(--color-gray-600);
  line-height: 1.8;
}

/* ============================================
   TESTIMONIAL
   ============================================ */
.testimonial-block {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-style: italic;
  color: var(--color-primary);
  line-height: 1.5;
  margin-bottom: var(--spacing-xl);
}

.testimonial-author {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-700);
}

.testimonial-role {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

/* ============================================
   CAROUSEL
   ============================================ */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 var(--spacing-md);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  color: var(--color-gray-700);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

/* ============================================
   FOOTER
   ============================================ */
.footer {
  background-color: var(--color-primary);
  color: rgba(255,255,255,0.7);
  padding: var(--spacing-4xl) 0 var(--spacing-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-2xl);
  margin-bottom: var(--spacing-3xl);
}

.footer-brand {
  grid-column: 1 / -1;
}

@media (min-width: 768px) {
  .footer-brand {
    grid-column: span 2;
  }
}

.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.footer-logo span {
  color: var(--color-accent);
}

.footer-desc {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 360px;
}

.footer-heading {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-white);
  margin-bottom: var(--spacing-lg);
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.footer-links a {
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--spacing-xl);
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-md);
}

.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md) var(--spacing-xl);
}

.footer-legal a {
  font-size: 0.8125rem;
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--color-accent);
}

.footer-copy {
  font-size: 0.8125rem;
}

/* ============================================
   RESPONSIVE UTILITIES
   ============================================ */
@media (max-width: 640px) {
  .container {
    padding-left: var(--spacing-md);
    padding-right: var(--spacing-md);
  }

  .section {
    padding: var(--spacing-3xl) 0;
  }

  .services-grid,
  .capabilities-grid {
    grid-template-columns: 1fr;
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .btn {
    width: 100%;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}

/* Focus States */
a:focus-visible,
button:focus-visible,
.tab-btn:focus-visible,
.carousel-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/**
 * GlobalStone — Main JavaScript
 * Handles: mobile nav, mega menu, tabs, carousel, scroll effects
 */

(function() {
  'use strict';

  // ============================================
  // Mobile Navigation
  // ============================================
  const menuToggle = document.querySelector('.menu-toggle');
  const navMobile = document.querySelector('.nav-mobile');

  if (menuToggle && navMobile) {
    menuToggle.addEventListener('click', function() {
      const isOpen = navMobile.classList.toggle('open');
      menuToggle.classList.toggle('active', isOpen);
      menuToggle.setAttribute('aria-expanded', isOpen);
      document.body.style.overflow = isOpen ? 'hidden' : '';
    });

    // Close mobile menu on link click
    navMobile.querySelectorAll('a').forEach(function(link) {
      link.addEventListener('click', function() {
        navMobile.classList.remove('open');
        menuToggle.classList.remove('active');
        menuToggle.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
      });
    });
  }

  // ============================================
  // Mobile Accordion
  // ============================================
  document.querySelectorAll('.mobile-accordion-header').forEach(function(header) {
    header.addEventListener('click', function() {
      const content = this.nextElementSibling;
      const isExpanded = this.getAttribute('aria-expanded') === 'true';

      // Close all others
      document.querySelectorAll('.mobile-accordion-header').forEach(function(h) {
        if (h !== header) {
          h.setAttribute('aria-expanded', 'false');
          h.nextElementSibling.classList.remove('open');
        }
      });

      this.setAttribute('aria-expanded', !isExpanded);
      content.classList.toggle('open', !isExpanded);
    });
  });

  // ============================================
  // Header Scroll Effect
  // ============================================
  const header = document.querySelector('.header');
  if (header) {
    let ticking = false;
    window.addEventListener('scroll', function() {
      if (!ticking) {
        window.requestAnimationFrame(function() {
          header.classList.toggle('scrolled', window.scrollY > 20);
          ticking = false;
        });
        ticking = true;
      }
    });
  }

  // ============================================
  // What We Do Tabs
  // ============================================
  const tabsWrapper = document.querySelector('.tabs-wrapper');
  if (tabsWrapper) {
    const tabBtns = tabsWrapper.querySelectorAll('.tab-btn');
    const tabPanels = tabsWrapper.querySelectorAll('.tab-panel');

    tabBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        const targetId = this.getAttribute('data-tab');

        tabBtns.forEach(function(b) {
          b.classList.remove('active');
          b.setAttribute('aria-selected', 'false');
        });
        tabPanels.forEach(function(p) {
          p.classList.remove('active');
        });

        this.classList.add('active');
        this.setAttribute('aria-selected', 'true');

        const targetPanel = document.getElementById(targetId);
        if (targetPanel) {
          targetPanel.classList.add('active');
        }
      });
    });
  }

  // ============================================
  // Carousel
  // ============================================
  const carousels = document.querySelectorAll('.carousel');
  carousels.forEach(function(carousel) {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const prevBtn = carousel.querySelector('.carousel-prev');
    const nextBtn = carousel.querySelector('.carousel-next');

    if (!track || slides.length === 0) return;

    let currentIndex = 0;

    function goToSlide(index) {
      if (index < 0) index = slides.length - 1;
      if (index >= slides.length) index = 0;
      currentIndex = index;
      track.style.transform = 'translateX(' + (-currentIndex * 100) + '%)';
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        goToSlide(currentIndex - 1);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        goToSlide(currentIndex + 1);
      });
    }
  });

  // ============================================
  // Mega Menu Click (for touch devices)
  // ============================================
  const megaTrigger = document.querySelector('.mega-menu-trigger');
  if (megaTrigger) {
    const triggerLink = megaTrigger.querySelector('.nav-link');
    const megaMenu = megaTrigger.querySelector('.mega-menu');

    if (triggerLink && megaMenu) {
      triggerLink.addEventListener('click', function(e) {
        // Only toggle on touch devices or when menu isn't already showing via hover
        if (window.innerWidth < 1024 || window.matchMedia('(hover: none)').matches) {
          e.preventDefault();
          megaMenu.classList.toggle('open');
        }
      });

      // Close on outside click
      document.addEventListener('click', function(e) {
        if (!megaTrigger.contains(e.target)) {
          megaMenu.classList.remove('open');
        }
      });
    }
  }

  // ============================================
  // Smooth scroll for anchor links
  // ============================================
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
    anchor.addEventListener('click', function(e) {
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;
      const target = document.querySelector(targetId);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });

})();
